# owner: platform
"""Snapping clock times to a fixed step for payroll."""

from typing import Iterable, List

from hourglass.models import Span
from hourglass.parsing import format_span


def _check_step(step: int) -> None:
    if step <= 0 or 60 % step:
        raise ValueError(
            f"step must divide an hour: {step}"
        )


def _snap(minute: int, step: int) -> int:
    """Nearest multiple of step, halves round up."""
    return (minute + step // 2) // step * step


def _label(span: Span) -> str:
    hours, rest = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {rest:02d}m)"


# ---
def round_labels(spans: Iterable[Span], step: int) -> List[str]:
    """Labels like 09:00-17:15 (8h 15m) after snapping."""
    _check_step(step)
    return [
        _label(Span(_snap(item.start, step),
                    _snap(item.end, step)))
        for item in spans
    ]
