# owner: platform
import unittest

from hourglass.models import Span
from hourglass.parsing import parse_span
from hourglass.rounding import round_labels


def labels(text, step):
    return round_labels([parse_span(text)], step)


class RoundLabelTests(unittest.TestCase):
    def test_already_on_step(self):
        self.assertEqual(
            labels("09:00-17:15", 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_rounds_to_nearest(self):
        self.assertEqual(
            labels("08:52-17:07", 15),
            ["09:00-17:00 (8h 00m)"]
        )

    def test_halfway_rounds_up(self):
        self.assertEqual(
            labels("09:07-10:22", 15),
            ["09:15-10:30 (1h 15m)"]
        )

    def test_many_spans_keep_order(self):
        spans = [Span(540, 600), Span(0, 60)]
        self.assertEqual(
            round_labels(spans, 60),
            ["09:00-10:00 (1h 00m)", "00:00-01:00 (1h 00m)"]
        )

    def test_end_of_day(self):
        self.assertEqual(
            labels("23:00-24:00", 30),
            ["23:00-24:00 (1h 00m)"]
        )

    def test_empty_list(self):
        self.assertEqual(round_labels([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 90, 120):
            with self.assertRaises(ValueError):
                round_labels([Span(0, 60)], step)

    def test_span_that_collapses_raises(self):
        with self.assertRaises(ValueError):
            labels("09:01-09:02", 15)


if __name__ == "__main__":
    unittest.main()
